import type { EventStatus } from "./events";

export type CandidateEventStatus = "review_needed" | "published" | "ignored";
export type CandidateEventConfidence = "high" | "medium" | "low";

export type CandidateEventSourceType =
    | "promoter"
    | "venue"
    | "band_official"
    | "ticket"
    | "sns"
    | "manual";

export type CandidateEvent = {
    id: string;
    artists: string[];
    tourName: string | null;
    // Use null when the date is not confirmed yet.
    date: string | null;
    prefecture: string | null;
    venue: string | null;
    genres: string[];
    // True when the main purpose is a visiting international artist's Japan show.
    isInternational: boolean;
    ticketUrl: string | null;
    officialUrl: string | null;
    sourceUrl: string;
    sourceType: CandidateEventSourceType;
    sourceName: string;
    confidence: CandidateEventConfidence;
    eventStatus: EventStatus;
    reviewStatus: CandidateEventStatus;
    reviewNotes: string;
    collectedAt: string;
    reviewedAt: string | null;
};

